   101	package hotel.reservations;
   102	
   103	import hotel.rooms.Room;
   104	import java.math.BigDecimal;
   105	import java.math.RoundingMode;
   106	import java.time.LocalDate;
   107	import java.time.Month;
   108	
   109	/**
   110	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   111	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   112	 * (half-even) at every step.
   113	 */
   114	public final class PriceCalculator {
   115	
   116	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   117	
   118	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   119	        return calculate(room, checkIn, checkOut, ratePlan, null);
   120	    }
   121	
   122	    /** The price under the rate plan; the company code is only used by the corporate plan. */
   123	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   124	        return ratePlan.price(this, room, checkIn, checkOut, companyCode);
   125	    }
   126	
   127	    /** The sum of the nights (with high season), less the given fraction of it as discount. */
   128	    Price nightlyPrice(Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal discountRate) {
   129	        int nights = 0;
   130	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   131	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   132	            subtotal = subtotal.add(nightPrice(room, night));
   133	            nights++;
   134	        }
   135	        BigDecimal discount = cents(subtotal.multiply(discountRate));
   136	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   137	    }
   138	
   139	    BigDecimal nightPrice(Room room, LocalDate night) {
   140	        BigDecimal nightlyRate = room.nightlyRate();
   141	        if (isHighSeason(night)) {
   142	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   143	        }
   144	        return cents(nightlyRate);
   145	    }
   146	
   147	    /** High season: from December 15 to the end of February, and the whole of July. */
   148	    static boolean isHighSeason(LocalDate date) {
   149	        Month month = date.getMonth();
   150	        return month == Month.JANUARY
   151	                || month == Month.FEBRUARY
   152	                || month == Month.JULY
   153	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   154	    }
   155	
   156	    static BigDecimal cents(BigDecimal value) {
   157	        return value.setScale(2, RoundingMode.HALF_EVEN);
   158	    }
   159	}
