   167	
   168	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
   169	public final class ReservationService {
   170	
   171	    static final String HOTEL_NAME = "Pousada Maré Alta";
   172	
   173	    private final Rooms rooms;
   174	    private final ReservationStore store;
   175	    private final PriceCalculator priceCalculator;
   176	    private final EmailSender emailSender;
   177	
   178	    public ReservationService(
   179	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
   180	        this.rooms = rooms;
   181	        this.store = store;
   182	        this.priceCalculator = priceCalculator;
   183	        this.emailSender = emailSender;
   184	    }
   185	
   186	    public synchronized Reservation create(NewReservation request) {
   187	        if (!request.checkOut().isAfter(request.checkIn())) {
   188	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
   189	        }
   190	        if (request.guests() < 1) {
   191	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
   192	        }
   193	        Room room = rooms.find(request.roomNumber())
   194	                .orElseThrow(() -> new HotelException(
   195	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
   196	        if (request.guests() > room.capacity()) {
   197	            throw new HotelException(
   198	                    ErrorCode.CAPACITY_EXCEEDED,
   199	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
   200	        }
   201	        Price price = priceCalculator.calculate(
   202	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
   203	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
   204	            throw new HotelException(
   205	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
   206	        }
   207	        return store.add(request, price);
   208	    }
   209	
   210	    public Reservation find(long reservationId) {
   211	        return store.find(reservationId)
   212	                .orElseThrow(() -> new HotelException(
   213	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
   214	    }
   215	
   216	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
   217	    public synchronized Reservation confirm(long reservationId) {
   218	        Reservation reservation = find(reservationId);
   219	        if (reservation.status() != ReservationStatus.PENDING) {
   220	            throw notAllowed(reservation, "confirm");
   221	        }
   222	        reservation.confirmPayment();
   223	        store.update(reservation);
   224	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
   225	        emailSender.send(
   226	                reservation.guest().email(),
   227	                "Reserva confirmada - " + HOTEL_NAME,
   228	                confirmationEmailBody(reservation, receipt));
   229	        return reservation;
   230	    }
   231	
   232	    /**
   233	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   234	     * reservation was never paid, so nothing comes back).
   235	     */
   236	    public synchronized Reservation cancel(long reservationId) {
   237	        Reservation reservation = find(reservationId);
   238	        if (reservation.status() != ReservationStatus.PENDING
   239	                && reservation.status() != ReservationStatus.CONFIRMED) {
   240	            throw notAllowed(reservation, "cancel");
   241	        }
   242	        BigDecimal refund = reservation.ratePlan().refund(reservation.amountPaid());
   243	        reservation.cancel(refund);
   244	        store.update(reservation);
   245	        return reservation;
   246	    }
   247	
   248	    public synchronized Reservation checkIn(long reservationId) {
   249	        Reservation reservation = find(reservationId);
   250	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   251	            throw notAllowed(reservation, "check in");
   252	        }
   253	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   254	        store.update(reservation);
   255	        return reservation;
   256	    }
   257	
   258	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   259	    public synchronized ReservationReceipt checkOut(long reservationId) {
   260	        Reservation reservation = find(reservationId);
   261	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   262	            throw notAllowed(reservation, "check out");
   263	        }
   264	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   265	        store.update(reservation);
   266	        return new ReservationReceipt(reservation, roomOf(reservation));
   267	    }
   268	
   269	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   270	    public ReservationReceipt receiptCopy(long reservationId) {
   271	        Reservation reservation = find(reservationId);
   272	        if (!reservation.isPaid()) {
   273	            throw notAllowed(reservation, "issue a receipt for");
   274	        }
   275	        return new ReservationReceipt(reservation, roomOf(reservation));
   276	    }
   277	
   278	    private Room roomOf(Reservation reservation) {
   279	        return rooms.find(reservation.roomNumber()).orElseThrow();
   280	    }
   281	
   282	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   283	        return "Olá, " + reservation.guest().name() + "!\n\n"
   284	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   285	                + receipt.text() + "\n"
   286	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   287	                + "Até breve!\n";
   288	    }
   289	
   290	    private static HotelException notAllowed(Reservation reservation, String operation) {
   291	        return new HotelException(
   292	                ErrorCode.OPERATION_NOT_ALLOWED,
   293	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   294	    }
   295	}

