    52	        }
    53	    },
    54	    /** Friday to Sunday (two nights) for a closed price all year round. Half comes back on cancellation. */
    55	    WEEKEND_PACKAGE {
    56	        private final Map<RoomType, BigDecimal> prices = Map.of(
    57	                RoomType.STANDARD, new BigDecimal("520.00"),
    58	                RoomType.DELUXE, new BigDecimal("820.00"),
    59	                RoomType.SUITE, new BigDecimal("1200.00"));
    60	
    61	        @Override
    62	        Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    63	            if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY || ChronoUnit.DAYS.between(checkIn, checkOut) != 2) {
    64	                throw invalid("the weekend package is from a Friday to the following Sunday");
    65	            }
    66	            BigDecimal packagePrice = prices.get(room.type());
    67	            return new Price(2, packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
    68	        }
    69	
    70	        @Override
    71	        BigDecimal refund(BigDecimal amountPaid) {
    72	            return PriceCalculator.cents(amountPaid.multiply(new BigDecimal("0.5")));
    73	        }
    74	    },
    75	    /** 7 nights or more: 10% off. Full refund. */
    76	    LONG_STAY {
    77	        @Override
    78	        Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    79	            if (ChronoUnit.DAYS.between(checkIn, checkOut) < 7) {
    80	                throw invalid("the long stay plan needs at least 7 nights");
    81	            }
    82	            return calculator.nightlyPrice(room, checkIn, checkOut, new BigDecimal("0.10"));
    83	        }
    84	
    85	        @Override
    86	        BigDecimal refund(BigDecimal amountPaid) {
    87	            return amountPaid;
    88	        }
    89	    };
    90	
    91	    /** The price of the stay under this plan; throws INVALID_REQUEST when the plan cannot be used for it. */
    92	    abstract Price price(PriceCalculator calculator, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode);
    93	
    94	    /** What goes back to the guest, given what they paid, when the reservation is cancelled. */
    95	    abstract BigDecimal refund(BigDecimal amountPaid);
    96	
    97	    private static HotelException invalid(String message) {
    98	        return new HotelException(ErrorCode.INVALID_REQUEST, message);
    99	    }
